import sys

def solve():
    a, b, c = map(int, sys.stdin.readline().split())

    # Calculate bonds
    x = (a + b - c) / 2
    y = (b - a + c) / 2
    z = (a - b + c) / 2

    # Check if all are non-negative integers
    if (a + b - c) % 2 == 0 and (b - a + c) % 2 == 0 and (a - b + c) % 2 == 0:
        if x >= 0 and y >= 0 and z >= 0:
            print(f"{int(x)} {int(y)} {int(z)}")
        else:
            print("Impossible")
    else:
        print("Impossible")

if __name__ == "__main__":
    solve()
"}

