def solve():
    n, h, l, r = map(int, input().split())
    a = list(map(int, input().split()))

    # dp[i][t] = maximum number of good sleeps we can get up to the i-th sleep with time t modulo h
    dp = [[-1] * h for _ in range(n + 1)]
    dp[0][0] = 0  # Start at time 0 with 0 good sleeps

    for i in range(1, n + 1):
        for t in range(h):
            if dp[i-1][t] == -1:
                continue

            # Option 1: sleep after a_i hours
            new_t = (t + a[i-1]) % h
            count = dp[i-1][t]
            if l <= new_t <= r:
                count += 1
            if dp[i][new_t] < count:
                dp[i][new_t] = count

            # Option 2: sleep after a_i - 1 hours
            new_t = (t + a[i-1] - 1) % h
            count = dp[i-1][t]
            if l <= new_t <= r:
                count += 1
            if dp[i][new_t] < count:
                dp[i][new_t] = count

    # Find the maximum number of good sleeps
    max_good = max(dp[n])
    print(max_good)

solve()
"}

