from math import factorial
from collections import Counter


def count_distinct_permutations(digits):
    freq = Counter(digits)
    total = factorial(len(digits))
    for count in freq.values():
        total //= factorial(count)
    return total


def generate_sorted_permutations(digits, max_count=3):
    freq = Counter(digits)
    result = []

    def backtrack(current, used):
        if len(result) >= max_count:
            return

        if len(current) == len(digits):
            result.append(int(''.join(current)))
            return

        for digit in sorted(freq.keys()):
            if freq[digit] > 0:
                freq[digit] -= 1
                current.append(str(digit))
                backtrack(current, used + [digit])
                current.pop()
                freq[digit] += 1

    backtrack([], [])
    return result


def solve():
    T = int(input())
    for _ in range(T):
        N = input().strip()
        digits = list(N)

        total = count_distinct_permutations(digits)

        if total < 3:
            print("Not possible!")
        else:
            permutations = generate_sorted_permutations(digits)
            third_smallest = permutations[2]
            third_largest = permutations[-3]
            print(f"{third_smallest} {third_largest}")

solve()
"}

