                    backtrack(current, used + [digit])
                    current.pop()
                    freq[digit] += 1
        else:
            for digit in sorted(freq.keys(), reverse=True):
                if freq[digit] > 0:
                    freq[digit] -= 1
                    current.append(str(digit))
