from math import factorial
from collections import Counter


def count_distinct_permutations(digits):
    freq = Counter(digits)
    total = factorial(len(digits))
    for count in freq.values():
        total //= factorial(count)
    return total


def generate_sorted_permutations(digits, max_count=3, ascending=True):
    freq = Counter(digits)
    result = []

    # Use an iterative approach to avoid recursion depth issues
    stack = [([], Counter(freq))]  # (current_digits, remaining_freq)

    while stack:
        current, freq = stack.pop()

        if len(result) >= max_count:
            continue

        if len(current) == len(digits):
            result.append(int(''.join(current)))
            continue

        # Try digits in ascending or descending order
        if ascending:
            for digit in sorted(freq.keys()):
                if freq[digit] > 0:
                    freq[digit] -= 1
                    stack.append((current + [str(digit)], freq.copy()))
                    freq[digit] += 1
        else:
            for digit in sorted(freq.keys(), reverse=True):
                if freq[digit] > 0:
                    freq[digit] -= 1
                    stack.append((current + [str(digit)], freq.copy()))
                    freq[digit] += 1

    return result


def solve():
    T = int(input())
    for _ in range(T):
        N = input().strip()
        digits = list(N)

        total = count_distinct_permutations(digits)

        if total < 3:
            print("Not possible!")
        else:
            # Get smallest 3
            smallest = generate_sorted_permutations(digits, max_count=3, ascending=True)
            # Get largest 3
            largest = generate_sorted_permutations(digits, max_count=3, ascending=False)

            third_smallest = smallest[2]
            third_largest = largest[2]
            print(f"{third_smallest} {third_largest}")

solve()
"}

