# Count the number of 1s and 2s
count_1 = a.count(1)
count_2 = a.count(2)

# Strategy: start with 2 if possible, then alternate 1 and 2
# This keeps prefix sums as small as possible and increases by 1 each time

# If we have at least one 2, start with 2
if count_2 > 0:
    result = [2]
    count_2 -= 1
    # Alternate between 1 and 2
    for i in range(n - 1):
        if i % 2 == 0:
            result.append(1)
        else:
            result.append(2)
        # Make sure we don't run out of either number
        if i % 2 == 0 and count_1 > 0:
            count_1 -= 1
        else:
            count_2 -= 1
else:
    # If no 2s, just output all 1s
    result = [1] * n

# Output the result
print(' '.join(map(str, result)))
