    segments = []
    for _ in range(n):
        l, r, w = map(int, input().split())
        segments.append((l, r, w))

    # Binary search on the answer
    left = 0
    right = 10**6  # max possible value

    def is_possible(range_low, range_high):
        # Check if we can connect 1 to m using only segments in [range_low, range_high]
        parent = list(range(m + 1))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            parent[find(x)] = find(y)

        for l, r, w in segments:
            if range_low <= w <= range_high:
                # Connect all points in this segment's range
                for i in range(l, r + 1):
                    union(i, i + 1)

        return find(1) == find(m)

    answer = 0
    while left <= right:
        mid = (left + right) // 2
        if is_possible(0, mid):
            answer = mid
            right = mid - 1
        else:
            left = mid + 1

