def max_overlap(a, b):
    """Calculate maximum overlap where a ends and b starts"""
    max_len = 0
    for i in range(min(len(a), len(b)), -1, -1):
        if a.endswith(b[:i]):
            max_len = i
            break
    return max_len


def solve():
    while True:
        n = int(input())
        if n == 0:
            break
        names = [input().strip() for _ in range(n)]

        # Calculate overlaps
        overlap = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i != j:
                    overlap[i][j] = max_overlap(names[i], names[j])

        # DP with bitmask
        INF = float('inf')
        dp = [[INF] * n for _ in range(1 << n)]

        # Base case: single string
        for i in range(n):
            dp[1 << i][i] = len(names[i])

        # DP transition
        for mask in range(1 << n):
            for i in range(n):
                if not (mask & (1 << i)):
                    continue
                for j in range(n):
                    if mask & (1 << j):
                        continue
                    new_mask = mask | (1 << j)
                    dp[new_mask][j] = min(
                        dp[new_mask][j],
                        dp[mask][i] + len(names[j]) - overlap[i][j]
                    )

        # Find minimum length
        result = min(dp[(1 << n) - 1][i] for i in range(n))
        print(result)

solve()
